-- ============================================================================
-- B5 FOLLOW-ON W2 (publish inputs in prompts and lessons): stimulation.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1,
-- route (a), and the spec docs/graded-field-audit/w2/stimulation.json (the
-- inputs, where each came from, and the key each reproduces through the
-- vendored engines). Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- BEGINNER
--   Prompt only, no field moves. Field 6 needs the fracturing and reservoir
--   pressures at the true vertical depth of 2380 m MD, which the generator
--   interpolated from the golden survey and profiles and no lesson or panel
--   prints (B5 finding 1). The prompt now states both at 2033.000 m TVD, with
--   the exact acid viscosity and the mD conversion, so the Darcy ceiling of m05
--   l02 is a hand calculation. Keys, expected values and tolerances are
--   unchanged.
--   PROMPT was: The job is placed at 2380 m measured depth.
--   PROMPT now: The job is placed at 2380 m measured depth. At the job's true
--   vertical depth of 2033.000 m the fracturing pressure, the closure stress
--   there, is 36554842.99 Pa and the reservoir pressure is 22468999.12 Pa. Take
--   the acid viscosity as exactly 0.001 Pa.s and 1 mD as 9.869233e-16 m2.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently, nobody is re-scored and no attempts guard is needed.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) with its
-- live fields (exact jsonb), as production holds it after W1 (it is
-- rewritten), OR its W2 prompt with the same fields (left alone). Anything
-- else raises and the whole file rolls back. A file that will write first
-- checks the W1 post-state and refuses without it. Generated by
-- docs/graded-field-audit/w2_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- stimulation / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'stimulation' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w2 stimulation refused: stimulation/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '35fd3a01ca3db5069f90319eef172f3b' and fields = '[{"key": "hawkins_s_before", "tol": 5E-7, "unit": "", "label": "Hawkins skin, before", "expected": 15.898452901112533}, {"key": "sandstone_volume_m3", "tol": 5E-7, "unit": "m3", "label": "Sandstone plan volume", "expected": 42.0945614782356}, {"key": "sandstone_s_after", "tol": 5E-7, "unit": "", "label": "Skin after the acid", "expected": 2.8382557567571496}, {"key": "carbonate_rwh_m", "tol": 5E-8, "unit": "m", "label": "Wormhole radius", "expected": 0.531456321656052}, {"key": "carbonate_skin", "tol": 5E-7, "unit": "", "label": "Carbonate skin", "expected": -1.4567517365442468}, {"key": "q_max_matrix_m3s", "tol": 5E-11, "unit": "m3/s", "label": "Maximum matrix rate", "expected": 0.00009644175015806953}]'::jsonb then 'old'
              when md5(prompt) = 'acac113efd039a6a3b2a9262741a4e15' and fields = '[{"key": "hawkins_s_before", "tol": 5E-7, "unit": "", "label": "Hawkins skin, before", "expected": 15.898452901112533}, {"key": "sandstone_volume_m3", "tol": 5E-7, "unit": "m3", "label": "Sandstone plan volume", "expected": 42.0945614782356}, {"key": "sandstone_s_after", "tol": 5E-7, "unit": "", "label": "Skin after the acid", "expected": 2.8382557567571496}, {"key": "carbonate_rwh_m", "tol": 5E-8, "unit": "m", "label": "Wormhole radius", "expected": 0.531456321656052}, {"key": "carbonate_skin", "tol": 5E-7, "unit": "", "label": "Carbonate skin", "expected": -1.4567517365442468}, {"key": "q_max_matrix_m3s", "tol": 5E-11, "unit": "m3/s", "label": "Maximum matrix rate", "expected": 0.00009644175015806953}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'stimulation' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w2 stimulation refused: stimulation/beginner matches neither its published form (prompt md5 35fd3a01ca3db5069f90319eef172f3b) nor its W2 form (prompt md5 acac113efd039a6a3b2a9262741a4e15), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W2 form
  if v_s0 = 'new' then
    raise notice 'w2 stimulation: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: production holds it, and the W2
  -- apply script checks all 34 files; this reads two of its rows
  if exists (select 1 from public.academy_capstones where app_slug = 'integrity' and tier = 'beginner' and active and md5(prompt) <> '0e0ac66d6b97e9f7f66b5055e1fddf7d')
     or exists (select 1 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active and md5(prompt) <> 'f362ed27e7d8766e7e51dcf1ca0e5e6e') then
    raise exception 'w2 stimulation refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for a well the lessons never treat. THE WELL is a 9-3/4 in hole, so the wellbore radius is 4.875 in, draining to 260 m, in rock of 0.4 mD. The job is placed at 2380 m measured depth. At the job''s true vertical depth of 2033.000 m the fracturing pressure, the closure stress there, is 36554842.99 Pa and the reservoir pressure is 22468999.12 Pa. Take the acid viscosity as exactly 0.001 Pa.s and 1 mD as 9.869233e-16 m2. THE DAMAGE has a permeability contrast of 8 and reaches out to 1.2 m. THE SANDSTONE PLAN targets an acid front at 0.8 m over a 65 m interval at 22 percent porosity, using a pore volume factor of 1.5. THE CARBONATE ALTERNATIVE pumps 12 cubic metres over the same interval at a pore volume to breakthrough of 1.0. Report: (1) the HAWKINS skin before any treatment; (2) the sandstone PLANNING VOLUME in cubic metres; (3) the sandstone skin AFTER the planned job; (4) the carbonate WORMHOLE RADIUS in metres; (5) the carbonate SKIN; and (6) the MAXIMUM MATRIX RATE in cubic metres per second. Traps. Field 3 is NOT zero. The front reaches 0.8 m and the damage reaches 1.2, so the job stops short and a residual skin survives it, which is the whole point of the plan. Field 6 takes the viscosity of the ACID, about 1e-3 Pa.s, and NOT the fracturing fluid: using a gel viscosity here understates the ceiling by more than two orders of magnitude and turns a routine job into an impossible one. Field 6 also takes the DAMAGED skin, because that is the well as it stands before any acid has been pumped into it. The frac pressure is the closure stress at the true vertical depth of 2380 m measured, which is not 2380 m. Free checks: field 1 must be large and positive, because a contrast of 8 over that radius is severe damage; field 3 must be positive and smaller than field 1; field 5 must be NEGATIVE, since a wormhole enlarges the effective wellbore; and field 6 must be small, because a damaged well in sub-millidarcy rock accepts fluid slowly.'
     where app_slug = 'stimulation' and tier = 'beginner' and active and md5(prompt) = '35fd3a01ca3db5069f90319eef172f3b';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w2 stimulation refused: stimulation/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'acac113efd039a6a3b2a9262741a4e15' and fields = '[{"key": "hawkins_s_before", "tol": 5E-7, "unit": "", "label": "Hawkins skin, before", "expected": 15.898452901112533}, {"key": "sandstone_volume_m3", "tol": 5E-7, "unit": "m3", "label": "Sandstone plan volume", "expected": 42.0945614782356}, {"key": "sandstone_s_after", "tol": 5E-7, "unit": "", "label": "Skin after the acid", "expected": 2.8382557567571496}, {"key": "carbonate_rwh_m", "tol": 5E-8, "unit": "m", "label": "Wormhole radius", "expected": 0.531456321656052}, {"key": "carbonate_skin", "tol": 5E-7, "unit": "", "label": "Carbonate skin", "expected": -1.4567517365442468}, {"key": "q_max_matrix_m3s", "tol": 5E-11, "unit": "m3/s", "label": "Maximum matrix rate", "expected": 0.00009644175015806953}]'::jsonb) from public.academy_capstones where app_slug = 'stimulation' and tier = 'beginner' and active) is not true then
    raise exception 'w2 stimulation refused: stimulation/beginner does not read back as its W2 form';
  end if;

  raise notice 'w2 stimulation: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
